-- =====================================================================
-- PCL Porsche Company Lens - 14_excel_import_export.sql
-- Exports the SQL extracts that the Excel model (PCL_05) imports.
-- Output folder: excel_import/ (copy to data/excel_import/ in the repository).
-- Run from the sql/ folder after 00_run_all.sql (and 12/13 exports).
-- =====================================================================
\copy (SELECT f.period_code, f.var_id, v.var_name, f.value, f.unit_std, f.value_label, f.origin, coalesce(f.source_id, ''), coalesce(f.source_ref, ''), coalesce(f.rounding, '') FROM core.fact_financial f JOIN core.dim_variable v USING (var_id) JOIN core.dim_period p USING (period_code) WHERE p.is_half_year AND p.in_analysis_window ORDER BY p.sort_key, f.var_id) TO 'excel_import/fact_long.csv' WITH (FORMAT csv, HEADER)
\copy (SELECT * FROM (SELECT d.period_code, 'model', d.model_id, m.model_name, (m.parent_model_id IS NULL) AS top_level, d.deliveries, d.value_label, coalesce(d.source_id, ''), coalesce(d.source_ref, '') FROM core.fact_deliveries_model d JOIN core.dim_model m USING (model_id) JOIN core.dim_period p USING (period_code) WHERE p.is_half_year AND p.in_analysis_window UNION ALL SELECT d.period_code, 'region', d.region_id, r.region_name, true, d.deliveries, d.value_label, coalesce(d.source_id, ''), coalesce(d.source_ref, '') FROM core.fact_deliveries_region d JOIN core.dim_region r USING (region_id) JOIN core.dim_period p USING (period_code) WHERE p.is_half_year AND p.in_analysis_window) x ORDER BY 1, 2, 3) TO 'excel_import/mix.csv' WITH (FORMAT csv, HEADER)
\copy (SELECT var_id, period_code, source_id, source_ref, reason FROM audit.data_gap ORDER BY var_id, period_code) TO 'excel_import/gaps.csv' WITH (FORMAT csv, HEADER)
\copy (SELECT check_id, min(check_name) AS check_name, count(*) FILTER (WHERE status = 'PASS') AS pass, count(*) FILTER (WHERE status = 'FAIL') AS fail, count(*) FILTER (WHERE status = 'INFO') AS info FROM audit.dq_result GROUP BY check_id ORDER BY check_id) TO 'excel_import/dq.csv' WITH (FORMAT csv, HEADER)
\copy (SELECT scenario_id, h2_margin_l0_pct, h2_margin_l1_pct, h2_margin_l2_pct FROM mart.v_guidance_2026 ORDER BY scenario_id) TO 'excel_import/ggrid.csv' WITH (FORMAT csv, HEADER)
\copy (SELECT scenario_id, h2_auto_ebitda_margin_pct, h2_auto_ncf_margin_pct FROM mart.v_guidance_2026_auto ORDER BY scenario_id) TO 'excel_import/gauto.csv' WITH (FORMAT csv, HEADER)
\copy (SELECT * FROM mart.v_guidance_2026_summary) TO 'excel_import/gsum.csv' WITH (FORMAT csv, HEADER)
\copy (SELECT guidance_id, metric, fiscal_year, low_value, high_value, unit_std, basis, value_label, source_id, source_ref FROM core.fact_guidance ORDER BY guidance_id) TO 'excel_import/guidance.csv' WITH (FORMAT csv, HEADER)
\copy (SELECT source_id, tier, publisher, document_title, doc_type, reporting_period, publication_date, url FROM audit.dim_source ORDER BY source_id) TO 'excel_import/sources.csv' WITH (FORMAT csv, HEADER)
\copy (SELECT assumption_id, statement, applies_to, rationale, sensitivity FROM mart.assumption ORDER BY assumption_id) TO 'excel_import/assumption.csv' WITH (FORMAT csv, HEADER)
\copy (SELECT period_code, topic, note, source_id, source_ref FROM mart.annotation ORDER BY period_code, topic) TO 'excel_import/annotation.csv' WITH (FORMAT csv, HEADER)
\copy (SELECT * FROM audit.audit_finding ORDER BY af_id) TO 'excel_import/findings.csv' WITH (FORMAT csv, HEADER)
\copy (SELECT * FROM mart.view_catalog ORDER BY view_name) TO 'excel_import/catalog.csv' WITH (FORMAT csv, HEADER)
\copy (SELECT a.period_code, a.ebit_l0_reported, a.ebit_l1_ex_realignment, a.ebit_l2_ex_realignment_tariffs, a.ebit_l3_hybrid_sensitivity, a.margin_l0_reported_pct, a.margin_l1_pct, a.margin_l2_pct, a.margin_l3_hybrid_pct, d.da_clean, r.rd_pl_charge, r.ebit_effect_of_cap_rate_change, s.asp_calc_eur_k, s.volume_effect, s.asp_effect, c.ncf_margin_pct, c.simple_cash_proxy, b.eff_residual_other_drivers, b.pp_residual_other_drivers FROM mart.v_ebit_adjusted a JOIN mart.v_da_clean d USING (period_code) JOIN mart.v_rd_capitalisation r USING (period_code) JOIN mart.v_asp_volume s USING (period_code) JOIN mart.v_cash_crosscheck c USING (period_code) LEFT JOIN mart.v_ebit_bridge_yoy b USING (period_code) ORDER BY a.sort_key) TO 'excel_import/sqlout.csv' WITH (FORMAT csv, HEADER)
